MERGE dbo.scratch AS t USING (SELECT id, name FROM dbo.customers) AS s ON t.customer_id = s.id AND t.note = s.name
WHEN MATCHED THEN UPDATE SET note = s.name
WHEN NOT MATCHED THEN INSERT (customer_id, note) VALUES (s.id, s.name);

